    private static readonly Lazy<BitmapSource> HeaderPictureLazy =
        new(CreateHeaderPicture);

    public static BitmapSource HeaderPicture => HeaderPictureLazy.Value;

    private static BitmapSource CreateHeaderPicture()
    {
        byte[] imageBytes = Convert.FromBase64String(HeaderPictureBase64);

        using MemoryStream stream = new(imageBytes, writable: false);

        BitmapImage image = new();
        image.BeginInit();
        image.CacheOption = BitmapCacheOption.OnLoad;
        image.CreateOptions = BitmapCreateOptions.PreservePixelFormat;
        image.DecodePixelWidth = 128;
        image.StreamSource = stream;
        image.EndInit();
        image.Freeze();

        return image;
    }
